template.solver:
def solve(p1, p2, g):
    best = 0
    for k in range(1, 401):
        if (p1 * k) % 100 != 0 or (p2 * k) % 100 != 0:
            continue
        E = p1 * k // 100
        L = p2 * k // 100
        for n in range(1, 400):
            ev = (n + k - 1) // 2 - (n - 1) // 2
            if ev != E:
                continue
            hi = min(n + k - 1, g - 1)
            less = max(0, hi - n + 1)
            if less == L:
                if best == 0 or n < best:
                    best = n
                break
    return best
